static const char *macws_settings_extension_bootstrap_name(
    const char *name) {
    if (!name) return name;
    const char *program = getprogname();
    const char *appExtension = getenv("MACWS_APP_EXTENSION");
    BOOL isSettingsHost = program && !strcmp(program, "System Settings");
    BOOL isSettingsExtension = appExtension && !strcmp(appExtension, "1");
    if (!isSettingsHost && !isSettingsExtension) return name;

    static const char extensionKitSuffix[] = ".extensionkit.internal";
    static const char viewBridgeSuffix[] = ".viewbridge";
    const char *suffix = NULL;
    size_t nameLength = strlen(name);
    size_t suffixLength = sizeof(extensionKitSuffix) - 1;
    if (nameLength > suffixLength &&
        !strcmp(name + nameLength - suffixLength, extensionKitSuffix)) {
        suffix = extensionKitSuffix;
    } else {
        suffixLength = sizeof(viewBridgeSuffix) - 1;
        if (nameLength > suffixLength &&
            !strcmp(name + nameLength - suffixLength, viewBridgeSuffix))
            suffix = viewBridgeSuffix;
    }
    if (!suffix) return name;

    size_t identifierLength = nameLength - suffixLength;
    if (identifierLength <= strlen("com.apple.") ||
        strncmp(name, "com.apple.", strlen("com.apple.")) != 0)
        return name;
    for (size_t index = 0; index < identifierLength; index++) {
        char character = name[index];
        if (!((character >= 'a' && character <= 'z') ||
              (character >= 'A' && character <= 'Z') ||
              (character >= '0' && character <= '9') ||
              character == '.' || character == '-')) return name;
    }
    static __thread char rewritten[512];
    int length = snprintf(
        rewritten, sizeof(rewritten),
        "com.macwsguide.settings-extension-carrier.%.*s%s",
        (int)identifierLength, name, suffix);
    return length > 0 && (size_t)length < sizeof(rewritten)
        ? rewritten : name;
}

static const char *macws_private_bootstrap_lsd_service_name(const char *name) {
    if (!name) return name;
    static const char lsdPrefix[] = "com.apple.lsd.";
    bool isLsdService = !strncmp(name, lsdPrefix, sizeof(lsdPrefix) - 1);
    bool isTranslocation = !strcmp(name, "com.apple.security.translocation");
    if (!isLsdService && !isTranslocation) return name;

    const char *role = getenv("MACWS_LSD_ROLE");
    bool systemFamily = role && !strcmp(role, "system");
    const char *suffix = isLsdService
        ? name + sizeof(lsdPrefix) - 1 : "security.translocation";
    if (role && !strcmp(role, "session") &&
        (!strcmp(suffix, "dissemination") || !strcmp(suffix, "encryption")))
        systemFamily = true;
    if (isTranslocation && !systemFamily)
        return "com.apple.macosbooter.security.translocation";

    static _Thread_local char rewritten[192];
    int length = snprintf(rewritten, sizeof(rewritten),
                          systemFamily
                              ? "com.apple.macosbooter.lsd.system.%s"
                              : "com.apple.macosbooter.lsd.%s",
                          suffix);
    return length > 0 && (size_t)length < sizeof(rewritten)
        ? rewritten : name;
}

static const char *macws_private_bootstrap_service_name(const char *name) {
    if (!name) return name;
    // The settings-extension launch proxy is the first iOS image submitted to
    // RunningBoard, so launchd allocates its managed endpoints under the proxy
    // unique bundle identifier. Ventura derives each peer name from the real
    // pane's LSApplicationExtensionRecord. Runtime `launchctl procinfo` showed
    // the corresponding carrier endpoint pair; map names only, preserving the
    // original managed ports and ExtensionKit/ViewBridge wire protocols.
    const char *settingsEndpoint =
        macws_settings_extension_bootstrap_name(name);
    if (settingsEndpoint != name) return settingsEndpoint;
    if (!strcmp(name, CARENDER_ORIG))
        return CARENDER_NEW;
    // Keep the static-interpose route complete.  Most clients also pass
    // through Metal_hooks.x's libxpc hooks, but hosted ExtensionKit processes
    // deliberately cannot dirty libxpc text after their sandbox is installed.
    // Runtime-confirmed by appearance-debug-marker-oslog.txt (2026-08-04):
    // Appearance issued 243 lookups for com.apple.lsd.modifydb which the
    // extension sandbox rejected with error 159, followed by
    // +[LSBundleRecord bundleRecordForCurrentProcess] returning nil.  These
    // names are the exact MachServices published by MacWS's Ventura daemons;
    // rewriting at dyld's bootstrap/xpc interpose boundary keeps the stock LS,
    // preferences, IconServices and SystemStatus protocols intact.
    if (!strcmp(name, "com.apple.systemstatus"))
        return "com.apple.macosbooter.systemstatus";
    if (!strcmp(name, "com.apple.systemstatus.publisher"))
        return "com.apple.macosbooter.systemstatus.publisher";
    if (!strcmp(name, "com.apple.systemstatus.activityattribution"))
        return "com.apple.macosbooter.systemstatus.activityattribution";
    if (!strcmp(name, "com.apple.coreservices.launchservicesd"))
        return "com.apple.macosbooter.coreservices.launchservicesd";
    if (!strcmp(name, "com.apple.cfprefsd.daemon")) {
        const char *mobileIdentity =
            getenv("MACWS_SYNTHETIC_MOBILE_USER");
        if (geteuid() == 501 && mobileIdentity &&
            strcmp(mobileIdentity, "1") == 0)
            return "com.apple.macosbooter.cfprefsd.agent.501";
        return "com.apple.macosbooter.cfprefsd.daemon";
    }
    if (!strcmp(name, "com.apple.cfprefsd.agent")) {
        // A real macOS login session owns one cfprefsd agent per uid.  iOS
        // has no user launchd domains, so MacWS publishes uid 0 and uid 501
        // agents under distinct outer-bootstrap names.  Route only processes
        // carrying the explicit synthetic uid-501 identity contract; root
        // desktop clients retain the established endpoint.
        const char *mobileIdentity =
            getenv("MACWS_SYNTHETIC_MOBILE_USER");
        if (geteuid() == 501 && mobileIdentity &&
            strcmp(mobileIdentity, "1") == 0)
            return "com.apple.macosbooter.cfprefsd.agent.501";
        return "com.apple.macosbooter.cfprefsd.agent";
    }
    // iPadOS publishes the AudioComponentRegistrar protocol from
    // mediaserverd.  Runtime-confirmed on 2026-09-15: an unisolated Ventura
    // AudioComponentFindNext request was serviced by mediaserverd pid 380 and
    // returned the iOS component catalog; DefaultOutput was absent even
    // though Ventura coreaudiod exposed a live Loopback output stream.  Keep
    // the unchanged Ventura registrar and all chroot clients on their own
    // bootstrap endpoint so AudioToolbox receives the matching macOS catalog.
    if (!strcmp(name, "com.apple.audio.AudioComponentRegistrar"))
        return "com.apple.macosbooter.audio.AudioComponentRegistrar";
    if (!strcmp(name, "com.apple.iconservices"))
        return "com.apple.macosbooter.iconservices";
    if (!strcmp(name, "com.apple.iconservices.store"))
        return "com.apple.macosbooter.iconservices.store";
    // Ventura Quick Look discovers both modern preview/thumbnail extensions
    // through pkd. Runtime oslog on the target showed those requests reaching
    // the iPadOS pkd (pid 1836), whose LaunchServices store has neither macOS
    // extension point. Keep PluginKit's protocol intact and isolate only the
    // colliding bootstrap name so clients and the stock Ventura pkd share the
    // same macOS LaunchServices database.
    if (!strcmp(name, PLUGINKIT_PKD_SERVICE_ORIG))
        return PLUGINKIT_PKD_SERVICE_NEW;
    // Runtime-confirmed via the target process image UUID and crash report:
    // Finder's public lookup activated iPadOS's uid-501 thumbnail agent
    // (BA2DE509-...), not the installed Ventura agent (6FF47A91-...). Keep the
    // stock QuickLookThumbnailing protocol and isolate only its two bootstrap
    // names so the Ventura client and listener meet in the same namespace.
    if (!strcmp(name, QUICKLOOK_THUMBNAILS_ORIG))
        return QUICKLOOK_THUMBNAILS_NEW;
    if (!strcmp(name, QUICKLOOK_THUMBNAILS_CACHE_DELETE_ORIG))
        return QUICKLOOK_THUMBNAILS_CACHE_DELETE_NEW;
    if (!strcmp(name, QUICKLOOK_SERVICE_ORIG))
        return QUICKLOOK_SERVICE_NEW;
    if (!strcmp(name, QUICKLOOKD_XPC_SERVICE_ORIG))
        return QUICKLOOKD_XPC_SERVICE_NEW;
    // RE-confirmed in Ventura 13.4 QuickLook UUID represented by the loaded
    // image at -[QLServerSatellite _connect]+0x68: legacy thumbnails create an
    // XPC-service connection to this exact bundle identifier. Runtime LLDB on
    // the iPad showed _connect and _sendSetupMessage... each run once while no
    // QuickLookSatellite process appeared and neither completion nor failure
    // handler fired. macos_gui.sh publishes the unchanged satellite protocol
    // as a root launchd Mach service because the chroot has no per-user XPC
    // bundle activation domain.
    if (!strcmp(name, QUICKLOOK_SATELLITE_ORIG))
        return QUICKLOOK_SATELLITE_NEW;
    if (!strcmp(name, "com.apple.carboncore.csnameddata"))
        return "com.apple.macosbooter.carboncore.csnameddata";
    // RE-confirmed from Ventura 13.4 CarbonCore's _initSeedService and the
    // stock com.apple.coreservicesd launch plist: CoreDrag asks this daemon
    // for the CSSeed v0x10001 client table before it creates a drag session.
    // Runtime-confirmed on the target: without this service CoreDragCreate
    // returns -900 after _CSCreateSeed("com.apple.coredragseed", ...).
    // Isolate the real Ventura daemon from any iPadOS CarbonCore endpoint;
    // both its bootstrap check-in and every injected client traverse here.
    if (!strcmp(name, CORESERVICESD_SERVICE_ORIG))
        return CORESERVICESD_SERVICE_NEW;
    if (!strcmp(name, DOCK_HELPER_SERVICE_ORIG))
        return DOCK_HELPER_SERVICE_NEW;
    const char *lsdEndpoint = macws_private_bootstrap_lsd_service_name(name);
    if (lsdEndpoint != name) return lsdEndpoint;
    // Ventura's four desktop CoreLocation endpoints are a different protocol
    // surface from iPadOS 16's similarly named services.  Runtime logs on the
    // target first showed `getLocationServicesCapableWithReplyBlock:` rejected
    // by the iOS synchronous NSXPC interface.  A subsequent run of Ventura's
    // real locationd reached CLLocationController only after its uid-205
    // cache tree existed, but then exited cleanly because this interposer also
    // rewrote the daemon's own desktop check-ins to the already-owned iOS
    // names.  Give all four desktop endpoints collision-free names and apply
    // the mapping symmetrically to the stock daemon and its stock clients.
    if (!strcmp(name, LOCATIOND_DESKTOP_AGENT_ORIG))
        return LOCATIOND_DESKTOP_AGENT_NEW;
    if (!strcmp(name, LOCATIOND_DESKTOP_REGISTRATION_ORIG))
        return LOCATIOND_DESKTOP_REGISTRATION_NEW;
    if (!strcmp(name, LOCATIOND_DESKTOP_SPI_ORIG))
        return LOCATIOND_DESKTOP_SPI_NEW;
    if (!strcmp(name, LOCATIOND_DESKTOP_SYNCHRONOUS_ORIG))
        return LOCATIOND_DESKTOP_SYNCHRONOUS_NEW;
    // Ventura's simulation controller is the stock, typed ingestion point for
    // CLLocation objects.  Keep it separate from iPadOS locationd's endpoint
    // so the native MacWS provider can feed the real iPad location into the
    // Ventura provider graph without replacing CLLocationManager results.
    if (!strcmp(name, LOCATIOND_SIMULATION_ORIG))
        return LOCATIOND_SIMULATION_NEW;
    // GeoServices wire formats are release-specific.  Runtime-confirmed on
    // iPadOS 16.3: Ventura Maps reached iOS geod but received GEOErrorDomain
    // Code=-10 ("No resources in request") and rendered only the empty tile
    // grid.  Route both the stock Ventura listener and its clients to a
    // collision-free endpoint; payloads still terminate in Ventura's real
    // com.apple.geod executable.
    if (!strcmp(name, GEOD_XPC_SERVICE))
        return GEOD_XPC_SERVICE_NEW;
    // CoreFoundation's Ventura _CFVolumeObserver asks DiskArbitration for the
    // initial mounted-volume set and a terminal "existing events received"
    // event.  Runtime sampling of the stock Ventura sharedfilelistd on
    // iPadOS 16.3 showed VolumeManager::volumes blocked forever in
    // dispatch_group_wait: the similarly named iPadOS endpoint accepted the
    // connection but never completed Ventura's observer protocol.  Keep the
    // stock Ventura daemon and all injected Ventura clients on a private,
    // collision-free bootstrap name; this preserves the original protocol
    // and leaves iPadOS diskarbitrationd and its storage clients untouched.
    if (!strcmp(name, DISKARBITRATIOND_SERVICE_ORIG))
        return DISKARBITRATIOND_SERVICE_NEW;
    // FrontBoard's BSServiceConnection resolves its domain endpoint with raw
    // bootstrap_look_up rather than xpc_connection_create_mach_service.
    // Keep this mapping identical to macws_private_chroot_service_name() so
    // Maps reaches Ventura UIKitSystem instead of iPadOS SpringBoard regardless
    // of which public transport wrapper the framework selects.
    if (!strcmp(name, FRONTBOARD_SYSTEM_ORIG))
        return FRONTBOARD_SYSTEM_NEW;
    if (!strcmp(name, VIEWBRIDGE_AUXILIARY_ORIG))
        return VIEWBRIDGE_AUXILIARY_NEW;
    if (!strcmp(name, EXTENSIONKIT_SERVICE_ORIG))
        return EXTENSIONKIT_SERVICE_NEW;
    if (!strcmp(name, HISERVICES_SERVICE_ORIG))
        return HISERVICES_SERVICE_NEW;
    if (!strcmp(name, AUTHD_SERVICE_ORIG))
        return AUTHD_SERVICE_NEW;
    // RE-confirmed against Ventura 13.4 DesktopServicesPriv at
    // TDSHelperContext::LaunchDesktopServicesHelper +0x7c..+0xa8: Finder
    // resolves this exact launchd Mach service before sending its Handshake.
    // Runtime-confirmed on iPadOS 16.3.1: the public endpoint returned
    // _xpc_error_connection_invalid, which the same function maps to -8062 at
    // +0x248. Keep both the unmodified helper and its clients on a private
    // endpoint so iPadOS's inactive, platform-incompatible job cannot win the
    // lookup.
    if (!strcmp(name, DESKTOP_SERVICES_HELPER_ORIG))
        return DESKTOP_SERVICES_HELPER_NEW;
    return name;
}

// Ventura's PluginKit expects LaunchServices' LSPlugInKitProxy to carry the
// code-signature entitlement dictionary.  On the target, the stock
// _LSRegisterPluginURL transaction creates the correct platform-1 record and
// bundle URL but serializes an empty dictionary.  This is not an absent
// entitlement: runtime diagnostics in pluginkit-pkd.log showed the empty
// LSPlugInKitProxy value, while SecCodeCopySigningInformation on that exact
// executable returned its signed `entitlements-DER` component.  Ventura
// codesign independently decoded the same component to
// `com.apple.security.app-sandbox = true`.
//
// RE-confirmed in Ventura 13.4 pkd UUID 76E60957-... at __TEXT+0x7848:
// -[PKDPlugIn diagnose] rejects only after -hasEntitlement: returns false.
// RE-confirmed in the loaded PlugInKit image at +0x1767c: that method reads
// -entitlements and then objectForKeyedSubscript:.  Repair the missing record
// payload at its source, LSPlugInKitProxy, by decoding the executable's real
// signed DER dictionary.  Invalid/missing DER, unsigned code, or a genuinely
// absent sandbox key remains absent and the stock PluginKit check still fails.
typedef const void *MacWSCEError;
typedef const void *MacWSCERuntime;
typedef void *MacWSCEQueryContext;
typedef MacWSCEError (*MacWSCEManagedContextFromCFDataFn)(
    MacWSCERuntime, CFDataRef, MacWSCEQueryContext *);
typedef MacWSCEError (*MacWSCEQueryContextToCFDictionaryFn)(
    MacWSCEQueryContext, CFDictionaryRef *);
typedef MacWSCEError (*MacWSCEReleaseManagedContextFn)(
    MacWSCEQueryContext *);

static uint32_t macws_read_code_signature_be32(const uint8_t *bytes) {
    uint32_t encoded = 0;
    memcpy(&encoded, bytes, sizeof(encoded));
    return CFSwapInt32BigToHost(encoded);
}

static BOOL macws_der_entitlements_match_code_directory(
    NSDictionary *information, NSData *derBlob) {
    CFStringRef codeDirectoryKey = CFStringCreateWithCString(
        kCFAllocatorDefault, "CodeDirectory", kCFStringEncodingUTF8);
    CFTypeRef codeDirectoryValue = codeDirectoryKey
        ? CFDictionaryGetValue((__bridge CFDictionaryRef)information,
                               codeDirectoryKey) : NULL;
    if (codeDirectoryKey) CFRelease(codeDirectoryKey);
    NSData *codeDirectory = codeDirectoryValue &&
        CFGetTypeID(codeDirectoryValue) == CFDataGetTypeID()
        ? (__bridge NSData *)codeDirectoryValue : nil;
    CFTypeRef cmsValue = CFDictionaryGetValue(
        (__bridge CFDictionaryRef)information, kSecCodeInfoCMS);
    NSData *cms = cmsValue && CFGetTypeID(cmsValue) == CFDataGetTypeID()
        ? (__bridge NSData *)cmsValue : nil;
    const uint8_t *directory = codeDirectory.bytes;
    const NSUInteger fixedHeaderSize = 40;
    if (!directory || codeDirectory.length < fixedHeaderSize || !derBlob ||
        derBlob.length < 8 || cms.length == 0)
        return NO;

    // CS_CodeDirectory v=0x20400 stores nSpecialSlots at +24, hashOffset at
    // +16, hashSize at +36 and hashType at +37.  Slot 7 is
    // CSSLOT_DER_ENTITLEMENTS and hashes the complete CS_GenericBlob,
    // including its magic and length.  This is the same byte relation
    // runtime-inspected in the target executable: SHA-256(blob) equals the
    // 32 bytes at hashOffset - 7 * hashSize.
    uint32_t magic = macws_read_code_signature_be32(directory);
    uint32_t directoryLength = macws_read_code_signature_be32(directory + 4);
    uint32_t hashOffset = macws_read_code_signature_be32(directory + 16);
    uint32_t specialSlotCount =
        macws_read_code_signature_be32(directory + 24);
    uint8_t hashSize = directory[36];
    uint8_t hashType = directory[37];
    const uint32_t derEntitlementsSlot = 7;
    if (magic != 0xfade0c02U || directoryLength > codeDirectory.length ||
        directoryLength < fixedHeaderSize ||
        specialSlotCount < derEntitlementsSlot ||
        hashSize != CC_SHA256_DIGEST_LENGTH ||
        hashType != 2 || hashOffset > directoryLength ||
        hashOffset < derEntitlementsSlot * hashSize)
        return NO;

    uint8_t digest[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256(derBlob.bytes, (CC_LONG)derBlob.length, digest);
    const uint8_t *signedDigest = directory + hashOffset -
        derEntitlementsSlot * hashSize;
    return memcmp(digest, signedDigest, sizeof(digest)) == 0;
}

static NSDictionary *macws_signed_entitlements_for_plugin_url(NSURL *url) {
    if (![url isKindOfClass:NSURL.class] || !url.isFileURL) return nil;
    NSURL *executableURL = [NSBundle bundleWithURL:url].executableURL;
    if (!executableURL) return nil;

    SecStaticCodeRef staticCode = NULL;
    CFDictionaryRef signingInformation = NULL;
    if (SecStaticCodeCreateWithPath((__bridge CFURLRef)executableURL, 0,
                                    &staticCode) != 0 || !staticCode)
        return nil;
    OSStatus status = SecCodeCopySigningInformation(
        staticCode, (1U << 0) | (1U << 1) | (1U << 2),
        &signingInformation);
    CFRelease(staticCode);
    if (status != 0 || !signingInformation) return nil;

    NSDictionary *information = (__bridge NSDictionary *)signingInformation;
    id dictionaryValue = [information objectForKey:
        (__bridge NSString *)kSecCodeInfoEntitlementsDict];
    NSDictionary *result = [dictionaryValue isKindOfClass:NSDictionary.class]
        ? [dictionaryValue copy] : nil;

    if (!result) {
        static dispatch_once_t ceOnce;
        static MacWSCERuntime ceRuntime;
        static MacWSCEError ceNoError;
        static MacWSCEManagedContextFromCFDataFn contextFromData;
        static MacWSCEQueryContextToCFDictionaryFn contextToDictionary;
        static MacWSCEReleaseManagedContextFn releaseContext;
        dispatch_once(&ceOnce, ^{
            void *handle = dlopen("/usr/lib/libCoreEntitlements.dylib",
                                  RTLD_NOW | RTLD_LOCAL);
            void *runtimeAddress = handle ? dlsym(handle, "CECRuntime")
                                          : NULL;
            void *noErrorAddress = handle ? dlsym(handle, "kCENoError")
                                          : NULL;
            ceRuntime = runtimeAddress
                ? *(MacWSCERuntime *)runtimeAddress : NULL;
            ceNoError = noErrorAddress
                ? *(MacWSCEError *)noErrorAddress : NULL;
            contextFromData = handle
                ? (MacWSCEManagedContextFromCFDataFn)dlsym(
                      handle, "CEManagedContextFromCFData") : NULL;
            contextToDictionary = handle
                ? (MacWSCEQueryContextToCFDictionaryFn)dlsym(
                      handle, "CEQueryContextToCFDictionary") : NULL;
            releaseContext = handle
                ? (MacWSCEReleaseManagedContextFn)dlsym(
                      handle, "CEReleaseManagedContext") : NULL;
        });

        void *derKeyAddress = dlsym(RTLD_DEFAULT,
                                    "kSecCodeInfoEntitlementsDER");
        CFStringRef derKey = derKeyAddress
            ? *(CFStringRef *)derKeyAddress : CFSTR("entitlements-DER");
        id derValue = [information objectForKey:(__bridge NSString *)derKey];
        NSData *derPayload = nil;
        if ([derValue isKindOfClass:NSData.class] &&
            macws_der_entitlements_match_code_directory(information,
                                                         derValue)) {
            NSData *signedBlob = derValue;
            // SecCodeCopySigningInformation returns the complete
            // CS_GenericBlob: big-endian CSMAGIC_EMBEDDED_DER_ENTITLEMENTS
            // (0xfade7172), length, then ASN.1.  CEManagedContextFromCFData
            // expects only the ASN.1 bytes.  Runtime-confirmed on the target:
            // the 107-byte value starts `fade7172 0000006b 7061...`; handing
            // it the header produced kCEErrorVerificationFailed, while the
            // signed payload itself starts at byte 8.
            if (signedBlob.length >= 8) {
                uint32_t encodedMagic = 0;
                uint32_t encodedLength = 0;
                memcpy(&encodedMagic, signedBlob.bytes,
                       sizeof(encodedMagic));
                memcpy(&encodedLength,
                       (const uint8_t *)signedBlob.bytes + 4,
                       sizeof(encodedLength));
                uint32_t magic = CFSwapInt32BigToHost(encodedMagic);
                uint32_t length = CFSwapInt32BigToHost(encodedLength);
                if (magic == 0xfade7172U &&
                    length == signedBlob.length && length > 8) {
                    derPayload = [signedBlob subdataWithRange:
                        NSMakeRange(8, length - 8)];
                }
            }
        }
        if (derPayload && ceRuntime && ceNoError &&
            contextFromData && contextToDictionary && releaseContext) {
            MacWSCEQueryContext context = NULL;
            MacWSCEError contextStatus = contextFromData(
                ceRuntime, (__bridge CFDataRef)derPayload, &context);
            if (contextStatus == ceNoError && context) {
                CFDictionaryRef decoded = NULL;
                MacWSCEError decodeStatus = contextToDictionary(
                    context, &decoded);
                releaseContext(&context);
                if (decodeStatus == ceNoError && decoded) {
                    if (CFGetTypeID(decoded) == CFDictionaryGetTypeID())
                        result = [(__bridge NSDictionary *)decoded copy];
                    CFRelease(decoded);
                }
            }
        }
    }
    CFRelease(signingInformation);
    return result;
}

typedef id (*MacWSLSPlugInKitProxyEntitlementsFn)(id, SEL);
static MacWSLSPlugInKitProxyEntitlementsFn
    g_macws_ls_plugin_proxy_entitlements;
static const void *g_macws_ls_plugin_proxy_signed_entitlements_key =
    &g_macws_ls_plugin_proxy_signed_entitlements_key;

static id macws_ls_plugin_proxy_entitlements(id proxy, SEL command) {
    id recorded = g_macws_ls_plugin_proxy_entitlements
        ? g_macws_ls_plugin_proxy_entitlements(proxy, command) : nil;
    if ([recorded isKindOfClass:NSDictionary.class] &&
        [(NSDictionary *)recorded count] != 0)
        return recorded;

    id cached = objc_getAssociatedObject(
        proxy, g_macws_ls_plugin_proxy_signed_entitlements_key);
    if (cached) return cached;
    SEL bundleURLSelector = sel_registerName("bundleURL");
    NSURL *bundleURL = [proxy respondsToSelector:bundleURLSelector]
        ? ((id (*)(id, SEL))objc_msgSend)(proxy, bundleURLSelector) : nil;
    NSDictionary *signedEntitlements =
        macws_signed_entitlements_for_plugin_url(bundleURL);
    if (signedEntitlements.count == 0) return recorded;
    objc_setAssociatedObject(
        proxy, g_macws_ls_plugin_proxy_signed_entitlements_key,
        signedEntitlements, OBJC_ASSOCIATION_COPY_NONATOMIC);
    if (getenv("MACWS_RUNTIME_DIAGNOSTICS")) {
        SEL identifierSelector = sel_registerName("pluginIdentifier");
        id identifier = [proxy respondsToSelector:identifierSelector]
            ? ((id (*)(id, SEL))objc_msgSend)(proxy, identifierSelector)
            : nil;
        fprintf(stderr,
                "#### MACWS-PKD restored signed entitlements plugin=%s "
                "URL=%s keys=%lu\n",
                [[identifier description] UTF8String] ?: "<nil>",
                [[bundleURL description] UTF8String] ?: "<nil>",
                (unsigned long)signedEntitlements.count);
    }
    return signedEntitlements;
}

static void macws_try_install_pkd_signed_entitlements_adapter(
    const struct mach_header *header, intptr_t slide) {
    (void)header;
    (void)slide;
    if (g_macws_ls_plugin_proxy_entitlements) return;
    Class proxyClass = objc_getClass("LSPlugInKitProxy");
    SEL selector = sel_registerName("entitlements");
    Method method = proxyClass
        ? class_getInstanceMethod(proxyClass, selector) : NULL;
    if (!method) return;
    MSHookMessageEx(proxyClass, selector,
                    (IMP)macws_ls_plugin_proxy_entitlements,
                    (IMP *)&g_macws_ls_plugin_proxy_entitlements);
    if (getenv("MACWS_RUNTIME_DIAGNOSTICS")) {
        fprintf(stderr,
                "#### MACWS-PKD installed signed-entitlements adapter "
                "class=%p orig=%p\n",
                proxyClass, g_macws_ls_plugin_proxy_entitlements);
    }
}

static void macws_install_pkd_signed_entitlements_adapter(void) {
    const char *program = getprogname();
    if (!program || strcmp(program, "pkd") != 0) return;
    _dyld_register_func_for_add_image(
        macws_try_install_pkd_signed_entitlements_adapter);
}

// Ventura cfprefsd selects its daemon/agent role from the launchd session when
// initWithRole: receives the automatic role (0).  RE-confirmed in the target
// CoreFoundation:
//   initWithRole:testMode: +0x080..+0x0f4 calls vproc_swap_string key 6,
//   compares the result with "System", then stores role 2 for System or role 1
//   for a login/background session.  iOS has no per-user launchd domains at
//   all (`launchctl help` states this explicitly), so the private agent job is
//   unavoidably classified as a second daemon and never executes checkIn.
//
// Preserve the stock role-selection code and translate only the missing
// launchd-session value for our dedicated private cfprefsd `agent` invocation.
// The original vproc call, errors, all other keys/processes, and daemon
// launches remain authoritative. strdup keeps the documented caller-owned
// result contract after releasing the original vproc string.
extern void *vproc_swap_string(void *vproc, int key,
                               const char *input, char **output);
static bool macws_is_private_cfprefsd_agent(void) {
    const char *program = getprogname();
    int *argc_pointer = _NSGetArgc();
    char ***argv_pointer = _NSGetArgv();
    return program && strcmp(program, "macws-cfprefsd") == 0 &&
        argc_pointer && *argc_pointer >= 2 && argv_pointer && *argv_pointer &&
        (*argv_pointer)[1] && strcmp((*argv_pointer)[1], "agent") == 0;
}

static void *vproc_swap_string_new(void *vproc, int key,
                                   const char *input, char **output) {
    void *error = vproc_swap_string(vproc, key, input, output);
    if (!error && key == 6 && input == NULL && output && *output &&
        strcmp(*output, "System") == 0 &&
        macws_is_private_cfprefsd_agent()) {
        char *background = strdup("Background");
        if (background) {
            free(*output);
            *output = background;
        }
    }
    return error;
}

static bool macws_synthetic_mobile_user_enabled(void);

// A normal macOS system bootstrap and login bootstrap never share
// _CS_DARWIN_USER_DIR: root lsd owns the system store while the login lsd owns
// a per-user store. MacWS has to submit both jobs to one outer launchd domain
// and currently runs GUI clients as uid 0, so uid alone would make both lsd
// roles clean/recover the same csstore concurrently. Preserve the stock
// confstr contract, but give only the explicitly tagged session lsd the
// dedicated user directory prepared by macos_gui.sh. All other confstr keys,
// processes, errors and buffer-size semantics remain native.
static size_t macws_confstr_new(int name, char *buffer, size_t length) {
    const char *role = getenv("MACWS_LSD_ROLE");
    const char *sessionDirectory = getenv("MACWS_LSD_SESSION_USER_DIR");
    if (name == _CS_DARWIN_USER_DIR && role && sessionDirectory &&
        !strcmp(role, "session") && sessionDirectory[0] == '/') {
        size_t required = strlen(sessionDirectory) + 1;
        if (buffer && length > 0) strlcpy(buffer, sessionDirectory, length);
        return required;
    }
    if (macws_synthetic_mobile_user_enabled()) {
        const char *mobileDirectory = NULL;
        switch (name) {
            case _CS_DARWIN_USER_DIR:
                mobileDirectory = "/var/folders/zz/macws_uid501/0/";
                break;
            case _CS_DARWIN_USER_CACHE_DIR:
                mobileDirectory = "/var/folders/zz/macws_uid501/C/";
                break;
            case _CS_DARWIN_USER_TEMP_DIR:
                mobileDirectory = "/var/folders/zz/macws_uid501/T/";
                break;
            default:
                break;
        }
        if (mobileDirectory) {
            size_t required = strlen(mobileDirectory) + 1;
            if (buffer && length > 0)
                strlcpy(buffer, mobileDirectory, length);
            return required;
        }
    }
    return confstr(name, buffer, length);
}

// launchdchrootexec can correctly enter the chroot as uid/gid 501, but the
// restored Ventura rootfs has no uid-501 account (`id -P mobile` and
// getpwuid(501) both return no record).  Runtime-confirmed consequences are
// upstream of 7DTD: a genuine uid-501 cfprefsd agent starts, yet a stock
// `defaults write` round-trip reports "Could not write domain" because
// CoreFoundation cannot resolve that login agent's home.
//
// Supply the missing login identity only to explicitly tagged uid-501
// processes.  A native directory-service record always wins.  No preference
// result, write status or application value is fabricated; cfprefsd still
// performs its normal plist I/O and atomic replacement below /Users/mobile.
static bool macws_synthetic_mobile_user_enabled(void) {
    const char *enabled = getenv("MACWS_SYNTHETIC_MOBILE_USER");
    return geteuid() == 501 && enabled && strcmp(enabled, "1") == 0;
}

static struct passwd g_macws_mobile_passwd = {
    .pw_name = "mobile",
    .pw_passwd = "*",
    .pw_uid = 501,
    .pw_gid = 501,
    .pw_change = 0,
    .pw_class = "",
    .pw_gecos = "Mobile User",
    .pw_dir = "/Users/mobile",
    .pw_shell = "/bin/bash",
    .pw_expire = 0,
};

static struct passwd *macws_getpwuid(uid_t uid) {
    struct passwd *record = getpwuid(uid);
    if (record || uid != 501 || !macws_synthetic_mobile_user_enabled())
        return record;
    return &g_macws_mobile_passwd;
}

static struct passwd *macws_getpwnam(const char *name) {
    struct passwd *record = getpwnam(name);
    if (record || !name || strcmp(name, "mobile") != 0 ||
        !macws_synthetic_mobile_user_enabled()) return record;
    return &g_macws_mobile_passwd;
}

static id (*macws_lsd_database_store_url_orig)(id, SEL) = NULL;
static id (*macws_lsd_database_store_url_uid_orig)(id, SEL, uid_t) = NULL;

static id macws_lsd_relocated_store_url(id originalURL) {
    const char *directory = getenv("MACWS_LSD_SESSION_USER_DIR");
    if (!originalURL || !directory || directory[0] != '/') return originalURL;
    NSString *directoryPath = [NSString stringWithUTF8String:directory];
    NSString *filename = [originalURL lastPathComponent];
    if (!directoryPath || !filename) return originalURL;
    NSURL *directoryURL = [NSURL fileURLWithPath:directoryPath
                                     isDirectory:YES];
    return [directoryURL URLByAppendingPathComponent:filename
                                         isDirectory:NO];
}

static id macws_lsd_database_store_url(id self, SEL command) {
    id originalURL = macws_lsd_database_store_url_orig
        ? macws_lsd_database_store_url_orig(self, command) : nil;
    return macws_lsd_relocated_store_url(originalURL);
}

static id macws_lsd_database_store_url_uid(id self, SEL command, uid_t uid) {
    id originalURL = macws_lsd_database_store_url_uid_orig
        ? macws_lsd_database_store_url_uid_orig(self, command, uid) : nil;
    return macws_lsd_relocated_store_url(originalURL);
}

static void macws_install_lsd_session_store_isolation(void) {
    const char *role = getenv("MACWS_LSD_ROLE");
    const char *directory = getenv("MACWS_LSD_SESSION_USER_DIR");
    if (!role || strcmp(role, "session") != 0 || !directory ||
        directory[0] != '/') return;

    static dispatch_once_t once;
    dispatch_once(&once, ^{
        Class defaultsClass = objc_getClass("_LSDefaults");
        if (!defaultsClass) return;
        SEL selector = sel_registerName("databaseStoreFileURL");
        Method method = class_getInstanceMethod(defaultsClass, selector);
        if (method) {
            MSHookMessageEx(defaultsClass, selector,
                            (IMP)macws_lsd_database_store_url,
                            (IMP *)&macws_lsd_database_store_url_orig);
        }
        selector = sel_registerName("databaseStoreFileURLWithUID:");
        method = class_getInstanceMethod(defaultsClass, selector);
        if (method) {
            MSHookMessageEx(defaultsClass, selector,
                            (IMP)macws_lsd_database_store_url_uid,
                            (IMP *)&macws_lsd_database_store_url_uid_orig);
        }
    });
}
extern kern_return_t bootstrap_look_up(mach_port_t bp, const char *name, mach_port_t *sp);
extern kern_return_t bootstrap_check_in(mach_port_t bp, const char *name, mach_port_t *sp);
extern kern_return_t bootstrap_look_up2(mach_port_t bp, const char *name,
                                        mach_port_t *sp, pid_t target_pid,
                                        uint64_t flags);
extern kern_return_t bootstrap_look_up3(mach_port_t bp, const char *name,
                                        mach_port_t *sp, pid_t target_pid,
                                        const unsigned char instance[16],
                                        uint64_t flags);
extern kern_return_t bootstrap_check_in2(mach_port_t bp, const char *name,
                                         mach_port_t *sp, uint64_t flags);
extern kern_return_t bootstrap_check_in3(mach_port_t bp, const char *name,
                                         mach_port_t *sp,
                                         unsigned char instance[16],
                                         uint64_t flags);

// Chromium 126's macOS MachPortRendezvousServer publishes one dynamic
// bootstrap name per browser PID. The browser calls bootstrap_check_in() to
// obtain the receive right; renderer/network/GPU children call
// bootstrap_look_up() and then use Chromium's unchanged Mach-message protocol
// to receive their shared-memory ports. iPadOS launchd does not provision
// these macOS application-scoped dynamic names. Runtime traces on iPadOS 16.3
// show the call entering the native bootstrap path without producing a usable
// completion while every child reaches ChildThreadImpl::EnsureConnected()
// about 15 seconds later.
//
// Preserve the protocol rather than bypassing the invariant. On that exact
// native failure, allocate a real receive right in the browser and let the
// iOS-native host keep only a send right under the exact name. Child lookup
// copies that send right back. The host never handles Chromium messages or
// shared-memory descriptors; it only supplies the missing bootstrap name
// lifetime. All other names and every successful native bootstrap operation
// remain untouched.
static bool macws_is_steam_mach_rendezvous_name(const char *name) {
    static const char prefix[] = MACWS_STEAM_MACH_RENDEZVOUS_PREFIX;
    if (!name || strncmp(name, prefix, sizeof(prefix) - 1) != 0) return false;
    const char *suffix = name + sizeof(prefix) - 1;
    if (!*suffix) return false;
    for (const char *cursor = suffix; *cursor; cursor++) {
        if (*cursor < '0' || *cursor > '9') return false;
    }
    return strnlen(name, 128) < 128;
}

// These wrappers run while CEF is still bringing up its process-global
// locks. stdio is not re-entrancy-safe there (the XPC name tracer below has
// the same constraint), so diagnostics must remain allocation-free and use
// the inherited descriptor directly.
static void macws_steam_mach_trace(const char *message) {
    if (!message || !getenv("MACWS_STEAM_PROCESS_DIAGNOSTICS")) return;
    (void)write(STDERR_FILENO, message, strlen(message));
}

static int macws_steam_mach_rendezvous_broker(
        const char *operation, const char *name, mach_port_t sendPort,
        mach_port_t *copiedPort) {
    if (copiedPort) *copiedPort = MACH_PORT_NULL;
    xpc_connection_t connection =
        macws_xpc_connection_create_mach_service_raw(
            MACWS_CONTROL_SERVICE,
            dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), 0);
    if (!connection) return EIO;
    xpc_connection_set_event_handler(connection,
        ^(xpc_object_t event) { (void)event; });
    xpc_connection_resume(connection);
    xpc_object_t request = xpc_dictionary_create(NULL, NULL, 0);
    if (!request) {
        xpc_connection_cancel(connection);
        xpc_release(connection);
        return ENOMEM;
    }
    xpc_dictionary_set_string(request, MACWS_CONTROL_KEY_OP, operation);
    xpc_dictionary_set_string(request, MACWS_STEAM_MACH_KEY_NAME, name);
    macws_steam_mach_trace("#### STEAM-MACH broker-send\n");
    if (MACH_PORT_VALID(sendPort))
        xpc_dictionary_set_mach_send(
            request, MACWS_STEAM_MACH_KEY_PORT, sendPort);
    xpc_object_t reply = xpc_connection_send_message_with_reply_sync(
        connection, request);
    int error = EIO;
    if (reply && xpc_get_type(reply) == XPC_TYPE_DICTIONARY) {
        error = (int)xpc_dictionary_get_int64(
            reply, MACWS_STEAM_MACH_KEY_ERROR);
        if (error == 0 && copiedPort) {
            *copiedPort = xpc_dictionary_copy_mach_send(
                reply, MACWS_STEAM_MACH_KEY_PORT);
            if (!MACH_PORT_VALID(*copiedPort)) error = EIO;
        }
    }
    if (reply) xpc_release(reply);
    xpc_release(request);
    xpc_connection_cancel(connection);
    xpc_release(connection);
    return error;
}

static kern_return_t macws_steam_mach_rendezvous_check_in(
        const char *name, mach_port_t *servicePort,
        kern_return_t nativeResult) {
    bool matchingName = macws_is_steam_mach_rendezvous_name(name);
    macws_steam_mach_trace("#### STEAM-MACH check-in entry\n");
    if (!servicePort || !matchingName) return nativeResult;

    mach_port_t receivePort = MACH_PORT_NULL;
    kern_return_t result = mach_port_allocate(
        mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &receivePort);
    if (result == KERN_SUCCESS) {
        result = mach_port_insert_right(
            mach_task_self(), receivePort, receivePort,
            MACH_MSG_TYPE_MAKE_SEND);
    }
    int brokerError = result == KERN_SUCCESS
        ? macws_steam_mach_rendezvous_broker(
            MACWS_STEAM_MACH_OP_REGISTER, name, receivePort, NULL)
        : EIO;
    if (result == KERN_SUCCESS && brokerError == 0) {
        // xpc_dictionary_set_mach_send copied the send right into hostd. The
        // browser owns only the receive right, matching bootstrap_check_in.
        (void)mach_port_mod_refs(
            mach_task_self(), receivePort, MACH_PORT_RIGHT_SEND, -1);
        *servicePort = receivePort;
        macws_steam_mach_trace("#### STEAM-MACH check-in broker-ok\n");
        return KERN_SUCCESS;
    }
    if (MACH_PORT_VALID(receivePort)) {
        (void)mach_port_mod_refs(
            mach_task_self(), receivePort, MACH_PORT_RIGHT_SEND, -1);
        (void)mach_port_mod_refs(
            mach_task_self(), receivePort, MACH_PORT_RIGHT_RECEIVE, -1);
    }
    macws_steam_mach_trace("#### STEAM-MACH check-in broker-failed\n");
    return nativeResult;
}

static kern_return_t macws_steam_mach_rendezvous_look_up(
        const char *name, mach_port_t *servicePort,
        kern_return_t nativeResult) {
    bool matchingName = macws_is_steam_mach_rendezvous_name(name);
    macws_steam_mach_trace("#### STEAM-MACH lookup entry\n");
    if (!servicePort || !matchingName) return nativeResult;
    mach_port_t copiedPort = MACH_PORT_NULL;
    int brokerError = macws_steam_mach_rendezvous_broker(
        MACWS_STEAM_MACH_OP_LOOKUP, name, MACH_PORT_NULL, &copiedPort);
    if (brokerError == 0 && MACH_PORT_VALID(copiedPort)) {
        *servicePort = copiedPort;
        macws_steam_mach_trace("#### STEAM-MACH lookup broker-ok\n");
        return KERN_SUCCESS;
    }
    macws_steam_mach_trace("#### STEAM-MACH lookup broker-failed\n");
    return nativeResult;
}

// Bounded, allocation-free cold-start service recorder.  Using fprintf from
// the static XPC interpose is not safe this early: the stdio path can re-enter
// framework initialization before Maps reaches NSApplicationMain.  This
// diagnostic writes at most 512 short records directly to the inherited log
// descriptor and never changes the requested service or its result.
static void macws_trace_xpc_name(const char *transport, const char *name) {
    if (!name || !getenv("MACWS_XPC_NAME_TRACE")) return;
    const char *filter = getenv("MACWS_XPC_NAME_TRACE_FILTER");
    if (filter && filter[0] && !strcasestr(name, filter)) return;
    static _Thread_local bool tracing = false;
    static _Atomic unsigned int recordCount = 0;
    if (tracing) return;
    unsigned int record = atomic_fetch_add_explicit(
        &recordCount, 1, memory_order_relaxed);
    if (record >= 512) return;

    tracing = true;
    char line[768];
    size_t used = 0;
    static const char prefix[] = "#### XPC-NAME ";
    size_t prefixLength = sizeof(prefix) - 1;
    memcpy(line + used, prefix, prefixLength);
    used += prefixLength;
    size_t transportLength = strnlen(transport ?: "unknown", 64);
    memcpy(line + used, transport ?: "unknown", transportLength);
    used += transportLength;
    line[used++] = ' ';
    line[used++] = '\'';
    size_t nameLength = strnlen(name, sizeof(line) - used - 3);
    memcpy(line + used, name, nameLength);
    used += nameLength;
    line[used++] = '\'';
    line[used++] = '\n';
    (void)write(STDERR_FILENO, line, used);
    tracing = false;
}

kern_return_t bootstrap_look_up_new(mach_port_t bp, const char *name, mach_port_t *sp) {
    const char *originalName = name;
    name = macws_private_bootstrap_service_name(name);
    macws_trace_xpc_name("bootstrap_look_up", originalName);
    if (name != originalName)
        macws_trace_xpc_name("bootstrap_look_up.mapped", name);
    bool steamRendezvous =
        macws_is_steam_mach_rendezvous_name(originalName);
    // The iPadOS bootstrap namespace cannot provide Chromium's per-browser
    // rendezvous endpoint. Route this exact, validated dynamic name through
    // hostd before entering the native routine; all unrelated names retain
    // the original bootstrap lookup path.
    kern_return_t result = steamRendezvous
        ? macws_steam_mach_rendezvous_look_up(
            originalName, sp, KERN_FAILURE)
        : bootstrap_look_up(bp, name, sp);
    if (steamRendezvous)
        macws_steam_mach_trace("#### STEAM-MACH lookup routed-result\n");
    if (!steamRendezvous && result != KERN_SUCCESS)
        result = macws_steam_mach_rendezvous_look_up(
            originalName, sp, result);
    if (getenv("MACWS_XPC_DEBUG")) {
        fprintf(stderr,
                "#### BOOTSTRAP look_up '%s'%s%s%s -> %#x port=%#x\n",
                originalName ?: "(null)", name != originalName ? " -> '" : "",
                name != originalName ? name : "", name != originalName ? "'" : "",
                result, sp ? *sp : MACH_PORT_NULL);
    }
    return result;
}
