            span == 0x288 &&
            *(uint32_t *)(record + 0x00) == 0x10000 &&
            *(uint32_t *)(record + 0x04) == 0x288 &&
            *(uint32_t *)(record + 0x24) == 0x90 &&
            *(uint32_t *)(record + 0x28) == 0x1e8 &&
            *(uint32_t *)(record + 0x2c) == 0x1b8 &&
            *(uint32_t *)(record + 0x30) == 0x30 &&
