            *(uint32_t *)(record + 0x1f0) == 0 &&
            *(uint32_t *)(record + 0x1f4) == 5 &&
            *(uint32_t *)(record + 0x1fc) == 0x15 &&
            *(uint32_t *)(record + 0x204) == 0x500 &&
            *(uint32_t *)(record + 0x208) == 3 &&
            *(uint32_t *)(record + 0x20c) == 0x100001e &&
            *(uint32_t *)(record + 0x214) == 0x15 &&
